"""Rebuild the standalone reader from its bundled ledger. Python standard library only."""
from pathlib import Path
import hashlib
import html
import json

ROOT = Path(__file__).resolve().parent.parent
ledger_path = ROOT / 'RESULTS_LEDGER.json'
D = json.loads(ledger_path.read_text(encoding='utf-8-sig'))
def e(x): return html.escape(str(x), quote=True)
def link(path, label): return f'<a href="{e(path)}">{e(label)}</a>'
def source(row):
    s = row.get('source', {})
    return link(s['path'], s.get('record', 'source')) if isinstance(s, dict) else e(s)
def table(head, rows):
    return '<div class="table-scroll" tabindex="0"><table><thead><tr>' + ''.join(f'<th scope="col">{e(x)}</th>' for x in head) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows) + '</tbody></table></div>'
def section(id, title, body): return f'<section id="{id}"><h2>{title}</h2>{body}</section>'
MATH1 = '<math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="Jet speed is at most square root of twice available work divided by participating mass. Contact pressure ceiling is impedance factor times this speed."><mrow><msub><mi>U</mi><mi>j</mi></msub><mo>≤</mo><msqrt><mfrac><mrow><mn>2</mn><msub><mi>E</mi><mi>av</mi></msub></mrow><msub><mi>m</mi><mi>j</mi></msub></mfrac></msqrt><mo>;</mo><mspace width="1em"/><msubsup><mi>Δp</mi><mi>c</mi><mi>ceiling</mi></msubsup><mo>=</mo><mfrac><mrow><msub><mi>Z</mi><mi>j</mi></msub><msub><mi>Z</mi><mi>t</mi></msub></mrow><mrow><msub><mi>Z</mi><mi>j</mi></msub><mo>+</mo><msub><mi>Z</mi><mi>t</mi></msub></mrow></mfrac><msqrt><mfrac><mrow><mn>2</mn><msub><mi>E</mi><mi>av</mi></msub></mrow><msub><mi>m</mi><mi>j</mi></msub></mfrac></msqrt></mrow></math>'
MATH2 = '<math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="One half prescribed mass times directed mass-qualified speed squared is at most water kinetic energy, which is at most activation available work; hence the speed bound."><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><msub><mi>m</mi><mo>*</mo></msub><msup><mi>U</mi><mn>2</mn></msup><mo>≤</mo><msub><mi>K</mi><mi>w</mi></msub><mo>≤</mo><msub><mi>Φ</mi><mi>a</mi></msub><mo>⇒</mo><mi>U</mi><mo>≤</mo><msqrt><mfrac><mrow><mn>2</mn><msub><mi>Φ</mi><mi>a</mi></msub></mrow><msub><mi>m</mi><mo>*</mo></msub></mfrac></msqrt></mrow></math>'
parts = []
parts.append(section('answer', 'The conditional answer', '<div class="verdict"><strong>No computed attainable velocity or receiver-pressure optimum is supplied.</strong> All 18 objectives, maximizing designs, attained lower values and certified upper values remain null. A prescribed participating water mass and complete available-work budget yield a conditional speed ceiling; an adopted contact model yields a conditional contact-pressure ceiling.</div><p>Stage1 and Stage2 remain closed under the owner-accepted loosened experimental-reference policy. Documentation completion does not establish strict acceptance, a certified PFC maximum or an actual-device maximum. This reader presents the source-bound ledger; '+link('FINAL_ANSWER.md','the complete final answer')+' and '+link('report/STAGE3_ENGINEERING_REPORT.pdf','the engineering PDF')+' contain the full narrative and derivation.</p>'))
parts.append(section('scope','Fixed problem and observer scope', '<p>PFP and PFH are treated separately. Initial unheated droplet diameter: 6 µm. Accommodation coefficient α<sub>c</sub> ∈ [0,1]. Stand-off γ = h/R<sub>m</sub> ≥ 1.25, with <strong>no finite upper application bound</strong>. The positive centre height h and same-model free-field maximum radius R<sub>m</sub> are in metres; the latter qualification remains unresolved. Coordinates are axisymmetric (r,z), with the rigid receiver at z = 0 and directed water speed w = −u<sub>z</sub>.</p><p>The whole-water quantile includes all water fractions, with no geometric jet mask. Its event interval ends at first axial liquid–liquid contact inside the cavity or first post-growth collapse minimum if no earlier impact exists. Tiny preparation extrema do not replace that event. Receiver gauge pressure is averaged over disk radii {2,10} µm and windows {2,20} ns wholly within the interval ending at first rebound maximum. The event must exist and the interval must contain the window. Wall viscous normal stress requires a separate check. '+source(D['scope']['observer_event_definitions_source'] if False else {'source':D['scope']['observer_event_definitions_source']})+'</p>'))
v = D['linear_example']['values']
parts.append(section('conditional','Accepted ceiling route', '<p>Before equation (1): available mechanical work E<sub>av</sub> ≥ 0 is in joules; prescribed participating mass m<sub>j</sub> &gt; 0 is in kilograms; nonnegative jet speed U<sub>j</sub> is in m/s; positive jet impedance Z<sub>j</sub> and nonnegative target impedance Z<sub>t</sub> are in Pa·s/m; contact gauge pressure Δp<sub>c</sub> is in pascals. Subscripts identify available work, jet, target and contact.</p><div class="equation">'+MATH1+'<span>(1)</span></div><p>The energy bound assumes lossless conversion into prescribed mass. The pressure expression assumes normal planar, weak-compression first contact before lateral release. Its impedance factor approaches Z<sub>j</sub> for a rigid target and equals Z<sub>j</sub>/2 for equal impedance. These assumptions do not automatically bound a finite-disk/time-averaged receiver objective.</p><p>The accepted illustrative 5 nJ water plug uses density 1000 kg/m³, sound speed 1500 m/s, radius 3 µm and length 50 µm: <strong>'+f"{v['energyVelocity_m_s']:.4f} m/s, {v['rigidPressure_Pa']/1e6:.4f} MPa rigid contact and {v['equalImpedancePressure_Pa']/1e6:.4f} MPa equal-impedance contact"+'</strong>. These are illustrative ceilings, not solved PFC outputs. '+source(D['linear_example'])+'. The complete accepted derivation is preserved in '+link('inputs/conditional_termtex/CONDITIONAL_SOLUTION.md','original equations E01–E24')+'.</p><p>The accepted Rayleigh solution is finite for a prescribed positive radius cutoff, and diverges when the imposed cutoff tends to zero. This singular limit belongs to an incompressible, inviscid, tension-free spherical model, not a physical jet or receiver maximum. Original E13–E22 preserve the integration and checks.</p>'))
cr=[]
for mass in D['scope']['whole_water_mass_pg']:
    vals=[next(x for x in D['ceilings'] if x['species']==s and x['mass_pg']==mass) for s in ['PFP','PFH']]
    cr.append([str(mass),f"{vals[0]['value']:.2f}",f"{vals[1]['value']:.2f}",'R|A',source(vals[0])+'<br>'+source(vals[1])])
parts.append(section('allowances','Exact-input available-work allowances', '<p>Before equation (2): prescribed whole-water mass m<sub>*</sub> &gt; 0 is in kilograms; U = U(m<sub>*</sub>,t) ≥ 0 is directed mass-qualified speed in m/s; time t is in seconds; full-vector water kinetic energy K<sub>w</sub>(t) and activation available work Φ<sub>a</sub> ≥ 0 are in joules.</p><div class="equation">'+MATH2+'<span>(2)</span></div><p>At least the prescribed mass has directed speed above the threshold, and full-vector speed is at least its directed component. Integrating kinetic energy gives the first inequality. The second requires a complete consistent availability budget, nonnegative remaining terms and no further useful input. This condition is <strong>not demonstrated for the loosened candidate030 trajectory</strong>.</p><p>The adopted fully uniform activation gives Φ<sub>a</sub> = 2.722572407203039 nJ (PFP) and 4.622122564638143 nJ (PFH). One pg is 10<sup>−15</sup> kg. The following tier R|A table is a conditional energy allowance, not a current-model certificate or achieved speed.</p>'+table(['Mass (pg)','PFP (m/s)','PFH (m/s)','Tier','Source record'],cr)+'<p>The accepted original ten-picogram illustrations remain <strong>737.5636 and 961.2492 m/s</strong>, using rounded 2.72 and 4.62 nJ. The exact-input row uses the unrounded preparation records; it does not revise the original accepted calculation. '+link('data/CONDITIONAL_ENERGY_CEILINGS.csv','Full-precision rebuilt CSV')+'. No numerical maximum is supplied for the registered receiver-pressure objectives.</p>'))
hr=[]
for row in D['historical']:
    value=row['value']/1e6 if row['units']=='Pa' else row['value']
    unit='MPa' if row['units']=='Pa' else row['units']
    hr.append([e(row['species']),e(row['group'].replace('_',' ')),f'{value:.2f} {unit}',e(row['tier']),str(row['gamma']),e(row['closure']),source(row)])
parts.append(section('history','Qualified historical predictions and estimates', '<p>'+e(D['historical_count_caveat'])+'</p>'+table(['Species','Stored group','Value','Tier','γ','Closure','Source'],hr)+'<p>P denotes a reduced-model sampled prediction; E denotes extrapolation or engineering estimate. The Mach 0.3 screen is a working cutoff in an incompressible model, not an error certificate. Speeds use a geometric sampled profile rather than the declared whole-water quantile. Sampled axial kinetic energy is a lower bound on full-vector energy of that sampled region. Pressure estimates assume mixed contact and spreading; they are not solved registered wall loads. None establishes a continuous optimum, certified lower bound or current engineering envelope. '+link('inputs/expert_resolution/tex/09_envelope.tex','Original tier definitions and assumptions')+'.</p>'))
ors=[]
for row in D['objective_results']:
    assert row['value'] is None and row['attained_lower'] is None and row['global_upper'] is None and row['maximizing_design'] is None
    cond=f"{row['water_mass_pg']} pg whole-water mass" if 'water_mass_pg' in row else f"{row.get('disk_radius_um',row.get('disk_um','?'))} µm radius / {row.get('window_ns','?')} ns"
    ors.append([e(row['id']),e(cond),'<code>null</code>','<code>null / null</code>','<code>null</code>',e(row['execution_status']),e(row['exit_disposition'])])
parts.append(section('objectives','All 18 declared objectives remain uncomputed', '<p>Null indicates missing evidence, never zero. Each slot lacks an event-complete registered observer trajectory, feasible attained design, refinement and global certificate.</p>'+table(['Objective ID','Condition','Attained value','Lower / upper','Maximizing design','Execution','Exit gate'],ors)+'<p>Certificate targets remain relative gaps ≤ 5% for velocity and ≤ 10% for pressure, numerical error ≤ one third of the respective tolerance and domain sensitivity ≤ one tenth. These are unestablished. '+link('RESULTS_LEDGER.json','Exact ledger with units, null fields and source hashes')+'.</p>'))
parts.append(section('diagnostics','Partial snapshot and metadata caveat', '<div class="caution"><strong>Candidate030 reaches 0.43 ns and 43 accepted steps only.</strong> Its transferred history ends at line 432. The snapshot establishes no full-cycle event or completed objective.</div><ul>'+''.join('<li>'+e(x)+'</li>' for x in D['metadata_caveats'])+'</ul><p>The inherited candidate018–030 assumptions and soft-pass stack are preserved. Earlier candidate028 failed at 0.44 ns and candidate029 stopped on the heat gate at 0.37 ns; the local candidate030 snapshot does not establish advancement beyond the former failure. Live-growing fields and debug binaries are omitted and unnecessary for this documentation scope. '+link('inputs/full_closure/runs/AXI_PFP_transport_candidate030_STAGE2_LOOSENED_PILOT001/history.csv','Frozen transferred history')+'.</p>'))
parts.append(section('waivers','Accepted waivers and independent-review dispositions', '<p>The seven owner-accepted Stage2 exit dispositions remain <strong>WAIVED</strong>, not measured scientific PASS:</p><ol>'+''.join('<li>'+e(x)+'</li>' for x in D['exit_waivers'])+'</ol><p>'+source({'source':D['waiver_authority']})+'. PASS means a check actually measured and satisfied; FAIL means a measured requirement was not satisfied; WAIVED records accepted policy authority; NOT_RUN records absent execution. These categories are distinct.</p><p>'+link('review/INDEPENDENT_REVIEW.md','Independent recomputation and all ten red-team answers')+' · '+link('INTERNAL_REVIEW.md','Integrated gate verdicts')+' · '+link('README.md','Delivery and reproducibility limits')+'</p><p>The actual-device maximum and dominant-assumption sensitivity ranking remain unresolved. Uniform activation, thermodynamic reference consistency, condensation closure, compressible flow, content uniformity and wall geometry may alter attainable output. The fixed detached model excludes optical breakdown, device transfer, gel/air loading and attached-cavity mechanisms. Constitutive and continuum assumptions do not validate a device.</p>'))
ids=[('answer','Answer'),('scope','Scope'),('conditional','Ceiling route'),('allowances','Mass allowances'),('history','Historical tiers'),('objectives','18 null objectives'),('diagnostics','Snapshot caveat'),('waivers','Waivers & review')]
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:6rem;color-scheme:light}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif;--bg:#f6f5f1;--fg:#172b35;--panel:#fff;--line:#ccd6d8;--accent:#096577;--muted:#52676e;--note:#e8f3f3;--warn:#fff1d6}html[data-theme=night]{color-scheme:dark}html[data-theme=night] body{--bg:#121e27;--fg:#e3ecef;--panel:#1b2b37;--line:#395160;--accent:#87d7e2;--muted:#b5c9d1;--note:#203b46;--warn:#483a25}a{color:var(--accent);text-underline-offset:.2em;overflow-wrap:anywhere}a:hover{text-decoration-thickness:3px}header{padding:2.5rem max(1rem,calc((100vw - 1150px)/2));background:var(--panel);border-bottom:1px solid var(--line)}header p{max-width:70ch;color:var(--muted)}h1{font:700 clamp(1.85rem,4vw,2.8rem)/1.2 Georgia,serif;margin:.6rem 0}h2{font:700 1.75rem/1.25 Georgia,serif;margin:0 0 1rem}main{max-width:1150px;margin:auto;padding:1.5rem 1rem 4rem}nav{display:flex;flex-wrap:wrap;gap:.5rem 1rem;max-width:1150px;margin:auto;padding:1rem}nav a{font-size:.9rem}section{padding:2rem;background:var(--panel);border:1px solid var(--line);border-radius:12px;margin:1.2rem 0}button{font:inherit;padding:.55rem 1rem;border:1px solid var(--line);border-radius:6px;background:var(--note);color:var(--fg);cursor:pointer;min-height:44px}button:focus-visible,a:focus-visible,.table-scroll:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.topbar{display:flex;gap:1rem;align-items:center;justify-content:space-between}.kicker{font-size:.8rem;text-transform:uppercase;letter-spacing:.13em;color:var(--muted)}.verdict,.caution{padding:1.2rem;border-left:4px solid var(--accent);background:var(--note)}.caution{background:var(--warn)}.table-scroll{overflow-x:auto;max-width:100%;border:1px solid var(--line);border-radius:6px}table{width:100%;border-collapse:collapse;font-size:.88rem;text-align:left}th{background:var(--note)}th,td{padding:.75rem;border-bottom:1px solid var(--line);vertical-align:top}td{min-width:5rem}td:last-child{min-width:13rem}tbody tr:last-child td{border-bottom:none}code{font:.85em ui-monospace,Consolas,monospace;background:var(--note);padding:.15rem .25rem;border-radius:3px}.equation{display:flex;align-items:center;justify-content:space-between;gap:1rem;overflow-x:auto;padding:1rem;border:1px solid var(--line)}math{font-size:1.3rem;margin:0;min-width:24rem}.equation span{color:var(--muted)}footer{font-size:.8rem;color:var(--muted);padding:1rem;overflow-wrap:anywhere}li{margin:.5rem 0}@media(max-width:650px){body{font-size:16px}header{padding:1.5rem 1rem}section{padding:1.25rem .9rem}.topbar{align-items:flex-start}main{padding:.5rem .6rem 2rem}h2{font-size:1.5rem}nav{gap:.4rem .8rem}.equation{padding:.5rem}math{font-size:1.15rem}td,th{padding:.55rem}}@media print{button,nav{display:none}body{--bg:white;--fg:black;--panel:white;--line:#bbb;--accent:#12596a}section{break-inside:avoid;border-radius:0}header{padding:1rem}main{max-width:none}}
'''
js="""(()=>{const root=document.documentElement,button=document.getElementById('theme-toggle');function setTheme(t){root.dataset.theme=t;button.textContent=t==='night'?'Switch to day':'Switch to night';button.setAttribute('aria-pressed',String(t==='night'));try{localStorage.setItem('stage3-reader-theme',t)}catch(e){}}let t='day';try{t=localStorage.getItem('stage3-reader-theme')||t}catch(e){}setTheme(t==='night'?'night':'day');button.addEventListener('click',()=>setTheme(root.dataset.theme==='night'?'day':'night'))})();"""
hashval=hashlib.sha256(ledger_path.read_bytes()).hexdigest()
output='<!doctype html><html lang="en" data-theme="day"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; img-src data:; font-src \'none\'; connect-src \'none\'; base-uri \'none\'"><title>Stage3 · Conditional cavitation engineering reference</title><style>'+css+'</style></head><body><header><div class="topbar"><div class="kicker">Stage3 · Experimental-reference documentation</div><button id="theme-toggle" type="button" aria-pressed="false">Switch to night</button></div><h1>Conditional cavitation engineering reference</h1><p>Accepted ceilings, historical predictions, diagnostic evidence and unresolved objectives. Owner-accepted loosened closure; scientific maximum unresolved.</p><p>'+link('FINAL_ANSWER.md','Final answer')+' · '+link('report/STAGE3_ENGINEERING_REPORT.pdf','PDF report')+' · '+link('RESULTS_LEDGER.json','Results ledger')+' · '+link('README.md','README')+'</p></header><nav aria-label="Reader sections">'+''.join(f'<a href="#{id}">{label}</a>' for id,label in ids)+'</nav><main>'+''.join(parts)+'<footer>Generated deterministically from bundled RESULTS_LEDGER.json by scripts/build_reader.py. Ledger SHA-256: '+hashval+'. Inline CSS, JavaScript and native MathML; no network is required. Relative source links travel with this folder.</footer></main><script>'+js+'</script></body></html>\n'
(ROOT/'READER.html').write_text(output,encoding='utf-8',newline='\n')
print(json.dumps({'output':'READER.html','sha256':hashlib.sha256(output.encode()).hexdigest(),'ledger_sha256':hashval,'objectives':len(D['objective_results']),'network_dependencies':0}))
